import { z } from "zod";

export const RunScope = z.object({
  runId: z.string().min(1),
  agent: z.enum(["nova", "cifix", "upgrade", "flaky", "bugfix"]),
  repo: z.string().regex(/^RhinoHealth\/[\w.-]+$/), // one repo, in our org
  branch: z.string().startsWith("nova/"),
  readRepos: z.array(z.string()).default([]),
  jiraKey: z.string().regex(/^RH-\d+$/).nullable(),
  expiresAt: z.iso.datetime(),
});
export type RunScope = z.infer<typeof RunScope>; // the type, for free

export const Note = z.object({ text: z.string().min(1).max(400) });

import { z } from "zod";
import { RunScope } from "@lab/shared/schemas";

const good = { runId: "run-1", agent: "nova", repo: "RhinoHealth/fcp", branch: "nova/RH-1234",
  jiraKey: "RH-1234", expiresAt: "2026-10-13T18:00:00Z" };
const scope = RunScope.parse(good); // typed as RunScope
console.log(scope.readRepos); // the default filled in

const bad = RunScope.safeParse({ ...good, repo: "evil/fcp", agent: "root" });
if (!bad.success) console.log(z.prettifyError(bad.error));

import { z } from "zod";
import { Note } from "@lab/shared/schemas";

if (route === "POST /v1/notes") {
  const parsed = Note.safeParse(JSON.parse(await readBody(req)));
  if (!parsed.success) return send(res, 400, { error: z.prettifyError(parsed.error) });
  notes.push(parsed.data.text);
  return send(res, 201, { count: notes.length });
}

import { z } from "zod";
import { RunScope } from "@lab/shared/schemas";

console.log("output:", z.toJSONSchema(RunScope).required);
console.log("input: ", z.toJSONSchema(RunScope, { io: "input" }).required);

export const Readiness = z.object({
  verdict: z.enum(["ready", "ask", "hand_back"]), reason: z.string(),
  size: z.enum(["small", "bigger", "fuzzy"]),  // bigger → grill; fuzzy → grill + 2–3 plans
  how_to_check: z.string(),  // empty = Nova sees no way to check it
  questions: z.array(z.string()).max(5),
});
export type Readiness = z.infer<typeof Readiness>;

for await (const msg of query({ prompt: ticket, options: {
  model: "claude-sonnet-5-5", effort: "low", tools: [], settingSources: [],  // routing table; no repo, no VM
  outputFormat: { type: "json_schema", schema: z.toJSONSchema(Readiness) },
} })) {
  if (msg.type === "result" && msg.subtype === "success") return Readiness.parse(msg.structured_output);
}
